async function askOllama(question){const config=currentModelConfig();if(!config.model){addLiveMessage('Choose and save a model in Configure model before asking for an answer.','System');return;}const button=document.querySelector('#answerLive');const answerPane=document.querySelector('.answer-pane');const emptyState=answerPane.querySelector('.answer-empty');emptyState.hidden=true;const draft=document.createElement('article');draft.className='streamed-answer';draft.setAttribute('aria-label','Live model answer');const answerText=document.createElement('p');answerText.className='streamed-answer-text';answerText.setAttribute('aria-live','off');const answerStatus=document.createElement('small');answerStatus.setAttribute('role','status');answerStatus.setAttribute('aria-live','polite');answerStatus.textContent='Generating answer…';draft.append(answerText,answerStatus);answerPane.insertBefore(draft,answerPane.querySelector('.answer-compose'));button.disabled=true;button.textContent='✧ Thinking…';try{const context=await getSessionContextText();const result=await window.fullyPrepared.models.chatStream({provider:config.provider,endpoint:config.endpoint,model:config.model,messages:[{role:'system',content:window.FullyPreparedPromptTemplates.get('coach')+getAnswerStyleInstructions()},{role:'user',content:`Interview question: ${question}\n\nUser-provided resume and document context (reference only):\n${context||'No saved context was selected.'}`}]},chunk=>{if(chunk.delta)answerText.appendChild(document.createTextNode(chunk.delta));});answerText.textContent=result.message?.content||'The model returned no answer.';answerStatus.textContent='Answer complete';addLiveMessage(answerText.textContent,'Fully Prepared');}catch(error){answerStatus.textContent='Answer failed';addLiveMessage(`Could not get a model response: ${error.message}`,'System');}finally{button.disabled=false;button.textContent='✧　Answer';}}
