function speakInterviewer(text){if(!text)return;let settings={};try{settings=JSON.parse(localStorage.getItem('fullyPreparedTtsSettings')||'{}')||{};}catch{localStorage.removeItem('fullyPreparedTtsSettings');}window.FullyPreparedSpeechOutput.enqueue(text,{...settings,provider:settings.provider||'system',rate:.96,voiceURI:settings.voiceURI||localStorage.getItem('fullyPreparedVoiceURI')||'',onError:error=>addLiveMessage(`Interviewer speech failed: ${error.message}`,'System')});}
async function interviewText(messages){const config=currentModelConfig();if(!config.model)return '';const instruction=localStorage.getItem('fullyPreparedInterviewInstruction')?.trim();const preparedMessages=instruction?messages.map((message,index)=>index===0&&message.role==='system'?{...message,content:`${message.content}\nUser-provided interviewer guidance: ${instruction}`} : message):messages;const result=await window.fullyPrepared.models.chat({provider:config.provider,endpoint:config.endpoint,model:config.model,messages:preparedMessages});return result.message?.content?.trim()||'';}
async function askNextInterviewQuestion(){const company=activeLocalSession?.company||document.querySelector('#companyInput')?.value.trim()||'the company';const role=activeLocalSession?.jobDescription||document.querySelector('#jobDescription')?.value.trim()||'the role';const context=await getSessionContextText();const fallback='Tell me about yourself and the experience that makes you a strong fit for this role.';try{const question=await interviewText([{role:'system',content:window.FullyPreparedPromptTemplates.get('interviewer')},{role:'user',content:`Company: ${company}\nJob description: ${role}\nCandidate reference context:\n${context||'None selected'}\nAsk the next appropriate interview question.`}]);currentInterviewQuestion=question||fallback;}catch(error){currentInterviewQuestion=fallback;}addLiveMessage(currentInterviewQuestion,'Interviewer');speakInterviewer(currentInterviewQuestion);if(activeLocalSession?.autoGenerate===true){addLiveMessage('Generating an optional answer suggestion. You remain in control of what you say.','System');void askOllama(currentInterviewQuestion);}}
