const callLanguage=document.querySelector('.live-controls select[aria-label="Call language"]');
const speechLanguages=[['auto','Auto detect'],['en','English'],['hi','Hindi'],['es','Spanish'],['fr','French'],['de','German'],['pt','Portuguese'],['ja','Japanese'],['ko','Korean'],['zh','Chinese']];
callLanguage.replaceChildren(...speechLanguages.map(([value,label])=>new Option(label,value)));
