  const company=document.querySelector('#companyInput').value.trim();
  const jobDescription=document.querySelector('#jobDescription').value.trim();
  if(!company||!jobDescription){event.preventDefault();event.stopImmediatePropagation();addLiveMessage('Company and job description are required before starting the interview.','System');return;}
  if(activeLocalSession?.status==='interrupted'){const prior=readCompletedSessions().filter(item=>item.id!==activeLocalSession.id);prior.push(activeLocalSession);localStorage.setItem('fullyPreparedSessions',JSON.stringify(prior));}
  const savedModel=JSON.parse(localStorage.getItem('fullyPreparedModel')||'null');
  document.querySelector('#messages').replaceChildren();currentInterviewQuestion='';voiceInterviewActive=false;sessionPaused=false;renderSessionPauseState();
