let microphoneStream=null;
async function connectMicrophone(){
  if(localStorage.getItem('fullyPreparedMicDisclosure')!=='accepted'){
    const consent=confirm('Microphone privacy: audio capture starts only after you accept and choose Record. Whisper.cpp mode sends the recording to the local endpoint shown in Configure model; browser recognition may use a service chosen by your runtime. The recognized text may then be sent to your selected AI model, including a hosted endpoint if you configured one. Continue to the microphone permission request?');
    if(!consent){addLiveMessage('Microphone was not connected. You can continue by typing an answer.','System');return false;}
    localStorage.setItem('fullyPreparedMicDisclosure','accepted');
  }
  if(!navigator.mediaDevices?.getUserMedia){addLiveMessage('Microphone access is not available in this build. Check Windows microphone permissions.','System');return false;}
  if(microphoneStream?.active){addLiveMessage('Microphone is already connected.','System');return true;}
  try{
    const deviceId=document.querySelector('#micDevice')?.value||undefined;
    microphoneStream=await navigator.mediaDevices.getUserMedia({audio:{deviceId:deviceId?{exact:deviceId}:undefined,echoCancellation:true,noiseSuppression:true,autoGainControl:true}});
    const track=microphoneStream.getAudioTracks()[0];
    document.querySelector('#micStatus').textContent='Mic connected';
    document.querySelector('#micStatus').classList.add('connected');
    addLiveMessage(`Microphone connected: ${track.label||'default microphone'}.`,'System');
    return true;
  }catch(error){
    document.querySelector('#micStatus').textContent='Mic unavailable';
    document.querySelector('#micStatus').classList.remove('connected');
    addLiveMessage(`Microphone connection failed: ${error.name==='NotAllowedError'?'permission was denied':error.message}. Enable microphone access for Fully Prepared in Windows Settings.`,'System');
    return false;
  }
}
document.querySelector('#stopLive').addEventListener('click',()=>{microphoneStream?.getTracks().forEach(track=>track.stop());microphoneStream=null;});
document.querySelector('#disconnectLive').addEventListener('click',()=>{microphoneStream?.getTracks().forEach(track=>track.stop());microphoneStream=null;});

async function populateMicrophones(){const selector=document.querySelector('#micDevice');if(!selector||!navigator.mediaDevices?.enumerateDevices)return;try{const devices=await navigator.mediaDevices.enumerateDevices();const microphones=devices.filter(device=>device.kind==='audioinput');selector.replaceChildren(new Option('Default microphone',''));microphones.forEach((device,index)=>selector.appendChild(new Option(device.label||`Microphone ${index+1}`,device.deviceId)));}catch(error){addLiveMessage(`Could not list microphones: ${error.message}`,'System');}}
document.querySelector('#micDevice').addEventListener('change',()=>{if(microphoneStream){microphoneStream.getTracks().forEach(track=>track.stop());microphoneStream=null;document.querySelector('#micStatus').textContent='Mic changed — reconnect';document.querySelector('#micStatus').classList.remove('connected');}});
document.querySelector('#liveInterview').addEventListener('transitionend',populateMicrophones);
populateMicrophones();
navigator.mediaDevices?.addEventListener('devicechange',populateMicrophones);
