const liveHeader=document.querySelector('.live-header');
const pauseButton=document.createElement('button');pauseButton.id='pauseLive';pauseButton.textContent='Pause';liveHeader.insertBefore(pauseButton,document.querySelector('#disconnectLive'));
pauseButton.type='button';pauseButton.setAttribute('aria-label','Pause interview session');pauseButton.setAttribute('aria-pressed','false');const sessionStateLabel=document.createElement('span');sessionStateLabel.className='session-state';sessionStateLabel.setAttribute('role','status');sessionStateLabel.setAttribute('aria-live','polite');sessionStateLabel.textContent='In progress';liveHeader.insertBefore(sessionStateLabel,document.querySelector('#disconnectLive'));
const timerLabel=document.createElement('span');timerLabel.id='sessionTimer';timerLabel.textContent='00:00';const freeLabel=[...liveHeader.querySelectorAll('span')].find(element=>element.textContent.includes('00:00'));if(freeLabel){freeLabel.innerHTML='◷ ';freeLabel.appendChild(timerLabel);freeLabel.append(' (Free)');}
function updateSessionClock(){const minutes=String(Math.floor(sessionClock/60)).padStart(2,'0');const seconds=String(sessionClock%60).padStart(2,'0');timerLabel.textContent=`${minutes}:${seconds}`;}
function runSessionClock(initialSeconds=0){sessionClock=initialSeconds;sessionClockRunning=true;clearInterval(sessionClockTimer);updateSessionClock();sessionClockTimer=setInterval(()=>{if(sessionClockRunning){sessionClock+=1;updateSessionClock();}},1000);}
function startSessionClock(){if(sessionPaused)return;runSessionClock(0);}
function resumeSessionClock(elapsedSeconds=0){runSessionClock(Math.max(0,Number(elapsedSeconds)||0));}
function renderSessionPauseState(){pauseButton.textContent=sessionPaused?'Resume':'Pause';pauseButton.setAttribute('aria-label',sessionPaused?'Resume interview session':'Pause interview session');pauseButton.setAttribute('aria-pressed',String(sessionPaused));sessionStateLabel.textContent=sessionPaused?'Paused':'In progress';liveInterview.classList.toggle('session-paused',sessionPaused);document.querySelector('#answerLive').disabled=sessionPaused;manualInput.disabled=sessionPaused;manualButtons[manualButtons.length-1].disabled=sessionPaused;voiceButton.disabled=sessionPaused;}
function pauseLiveSession(){if(!activeLocalSession||sessionPaused)return;sessionPaused=true;voiceInterviewActive=false;sessionClockRunning=false;window.speechSynthesis.cancel();if(voiceRecorder?.state==='recording'){discardVoiceRecording=true;voiceRecorder.stop();}if(speechRecognizer&&listeningForAnswer){discardBrowserSpeechTranscript=true;speechRecognizer.stop();}microphoneStream?.getTracks().forEach(track=>track.stop());microphoneStream=null;document.querySelector('#micStatus').textContent='Mic off';document.querySelector('#micStatus').classList.remove('connected');activeLocalSession=window.FullyPreparedSessionState.setSessionPaused(activeLocalSession,true);renderSessionPauseState();addLiveMessage('Session paused. Your timer is stopped and microphone is disconnected.','System');persistActiveSession();}
function resumeLiveSession(){if(!activeLocalSession||!sessionPaused)return;sessionPaused=false;voiceInterviewActive=true;sessionClockRunning=true;activeLocalSession=window.FullyPreparedSessionState.setSessionPaused(activeLocalSession,false);renderSessionPauseState();document.querySelector('#micStatus').textContent='Mic off';addLiveMessage('Session resumed. Reconnect your microphone when you are ready.','System');persistActiveSession();if(currentInterviewQuestion)speakInterviewer(currentInterviewQuestion);else void askNextInterviewQuestion();}
function toggleSessionPause(){if(sessionPaused)resumeLiveSession();else pauseLiveSession();}
pauseButton.addEventListener('click',toggleSessionPause);
document.querySelector('#createMockSession').addEventListener('click',()=>setTimeout(startSessionClock,300));
document.querySelector('#disconnectLive').addEventListener('click',()=>{sessionClockRunning=false;clearInterval(sessionClockTimer);persistActiveSession();});

// Product foundation services: validation, local diagnostics, onboarding, and keyboard access.
function logAppEvent(type){if(localStorage.getItem('fullyPreparedCrashCapture')!=='true')return;try{const entries=JSON.parse(localStorage.getItem('fullyPreparedDiagnostics')||'[]');entries.push({type:String(type).slice(0,48),at:new Date().toISOString()});localStorage.setItem('fullyPreparedDiagnostics',JSON.stringify(entries.slice(-50)));}catch(error){localStorage.removeItem('fullyPreparedDiagnostics');}}
function showFoundationToast(message,kind='info'){let toast=document.querySelector('#foundationToast');if(!toast){toast=document.createElement('div');toast.id='foundationToast';toast.setAttribute('role','status');toast.setAttribute('aria-live','polite');document.body.appendChild(toast);}toast.textContent=message;toast.className=`foundation-toast ${kind}`;clearTimeout(showFoundationToast.timer);showFoundationToast.timer=setTimeout(()=>toast.classList.add('hidden'),4200);}
window.addEventListener('error',()=>{logAppEvent('renderer-error');showFoundationToast('Something went wrong. Your local data was not changed.','error');});
window.addEventListener('unhandledrejection',()=>{logAppEvent('renderer-operation-failed');showFoundationToast('A local operation could not finish.','error');});
document.querySelector('#saveModel').addEventListener('click',event=>{const model=document.querySelector('#modelName').value.trim();const endpoint=document.querySelector('#endpointUrl').value.trim();if(!model||!endpoint){event.preventDefault();event.stopImmediatePropagation();showFoundationToast('Enter both a model name and endpoint URL.','error');return;}try{new URL(endpoint);logAppEvent('model-settings-saved',model);}catch(error){event.preventDefault();event.stopImmediatePropagation();showFoundationToast('Enter a valid endpoint URL, such as http://127.0.0.1:11434.','error');}},{capture:true});
function showOnboarding(){if(localStorage.getItem('fullyPreparedOnboardingDone'))return;const overlay=document.createElement('div');overlay.id='foundationOnboarding';overlay.innerHTML='<div class="onboarding-card"><div class="onboarding-mark">✦</div><p class="settings-kicker">WELCOME TO FULLY PREPARED</p><h2>Your local interview workspace</h2><p>Connect Ollama, create a mock interview, and practice with your microphone. Your settings and transcripts stay on this device unless you choose an external provider.</p><div class="onboarding-actions"><button id="skipOnboarding">Skip</button><button id="finishOnboarding" class="primary">Get started</button></div></div>';document.body.appendChild(overlay);const finish=()=>{localStorage.setItem('fullyPreparedOnboardingDone','1');overlay.remove();logAppEvent('onboarding-completed');};document.querySelector('#finishOnboarding').addEventListener('click',finish);document.querySelector('#skipOnboarding').addEventListener('click',finish);}
showOnboarding();
