function setupUsernamePrompt(){if(localStorage.getItem('fullyPreparedUsername')){renderUsername();return;}const existing=document.querySelector('#foundationOnboarding');const overlay=existing||document.createElement('div');if(!existing){overlay.id='foundationOnboarding';document.body.appendChild(overlay);}const card=overlay.querySelector('.onboarding-card');if(card&&!card.querySelector('#usernameInput')){const field=document.createElement('label');field.className='username-field';field.innerHTML='<span>What should we call you?</span><input id="usernameInput" maxlength="32" autocomplete="name" placeholder="Your name" />';const actions=card.querySelector('.onboarding-actions');card.insertBefore(field,actions);}const input=document.querySelector('#usernameInput');const save=event=>{const username=input?.value.trim();if(!username){event.preventDefault();event.stopImmediatePropagation();showFoundationToast('Please enter a name to continue.','error');input?.focus();return;}localStorage.setItem('fullyPreparedUsername',username);renderUsername();};if(document.querySelector('#finishOnboarding'))document.querySelector('#finishOnboarding').addEventListener('click',save,{capture:true});if(document.querySelector('#skipOnboarding'))document.querySelector('#skipOnboarding').addEventListener('click',()=>{localStorage.setItem('fullyPreparedUsername','User');renderUsername();},{capture:true});if(input&&!existing)input.focus();}
