function applyDashboardFilters(){const query=(document.querySelector('#sessionSearch')?.value||'').trim().toLowerCase();const filter=document.querySelector('#sessionFilter')?.value||'all';const cards=[...document.querySelectorAll('#sessionCards .session-card')];cards.forEach(card=>{const matchesText=!query||card.textContent.toLowerCase().includes(query);const type=card.dataset.sessionType||'Mock interview';const matchesType=filter==='all'||(filter==='mock'&&type==='Mock interview')||(filter==='interview'&&type==='Interview')||(filter==='regular'&&type==='Regular call');card.hidden=!(matchesText&&matchesType);});const sort=document.querySelector('#sessionSort')?.value||'newest';document.querySelector('#sessionCards')?.replaceChildren(...cards.sort((a,b)=>{const at=Date.parse(a.dataset.startedAt||'')||0;const bt=Date.parse(b.dataset.startedAt||'')||0;return sort==='oldest'?at-bt:bt-at;}));}
