function readCompletedSessions(){try{return JSON.parse(localStorage.getItem('fullyPreparedSessions')||'[]');}catch(error){localStorage.removeItem('fullyPreparedSessions');return [];}}
function renderSessionHistory(){
  const sessions=readCompletedSessions();
  if(activeLocalSession?.status==='interrupted'&&!sessions.some(item=>item.id===activeLocalSession.id))sessions.push(activeLocalSession);
  const section=document.querySelector('#sessionHistory'),cards=document.querySelector('#sessionCards');
  if(!sessions.length){section.classList.add('hidden');cards.replaceChildren();return;}
  section.classList.remove('hidden');cards.replaceChildren();
  sessions.sort((a,b)=>(Date.parse(b.startedAt)||0)-(Date.parse(a.startedAt)||0));
  for(const session of sessions){
    const card=document.createElement('article');card.className='session-card';card.dataset.startedAt=session.startedAt||'';card.dataset.sessionType=session.type||'Mock interview';
    const title=document.createElement('h3');title.textContent=session.company||'Untitled interview';
    const role=document.createElement('p');role.textContent=(session.jobDescription||'Mock interview').slice(0,90);
    const meta=document.createElement('div');meta.className='session-meta';
    const type=document.createElement('span');type.className='session-type';type.textContent=session.type||'Mock interview';
    const elapsed=Math.max(0,Number(session.elapsedSeconds)||0),duration=document.createElement('span');duration.className='session-duration';duration.textContent=`${Math.floor(elapsed/60)} min${elapsed%60?` ${elapsed%60} sec`:''}`;meta.append(type,duration);
    const date=new Date(session.startedAt),dateLabel=document.createElement('p');dateLabel.textContent=Number.isNaN(date.getTime())?'Date unavailable':date.toLocaleString();
    const status=document.createElement('p');status.className='session-status';status.textContent=`● ${session.status==='completed'?'Completed':session.status==='interrupted'?'Interrupted — resume available':'In progress'}`;
    const actions=document.createElement('div');actions.className='session-actions';
    const transcript=document.createElement('button');transcript.className='primary';transcript.textContent=session.saveTranscript===false?'View details':'View transcript';transcript.addEventListener('click',()=>openTranscript(session));actions.append(transcript);
    const menu=document.createElement('details');menu.className='session-actions-menu';
    const summary=document.createElement('summary');summary.textContent='More actions';menu.append(summary);
    const addMenuAction=(label,onClick,danger=false)=>{const button=document.createElement('button');button.type='button';button.textContent=label;if(danger)button.className='danger';button.addEventListener('click',()=>{menu.open=false;onClick();});menu.append(button);};
    addMenuAction('Export transcript',()=>exportTranscript(session));
    if(session.status==='interrupted')addMenuAction('Resume session',()=>resumeSavedSession(session));
    addMenuAction('Delete session',()=>deleteSavedSession(session),true);
    actions.append(menu);card.append(title,role,meta,dateLabel,status,actions);cards.append(card);
  }
  applyDashboardFilters?.();
}
function exportTranscript(session){const transcript=(session.messages||[]).map(item=>`${item.source||'Session'}\n${item.text||''}`).join('\n\n');const body=`${session.company||'Mock interview'}\n${session.jobDescription||''}\nStarted: ${session.startedAt||'Unknown'}\nStatus: ${session.status||'Unknown'}\n\n${transcript}`;const fileName=(session.company||'mock-interview').replace(/[^a-z0-9-_]+/gi,'-').replace(/^-|-$/g,'').toLowerCase()||'mock-interview';const url=URL.createObjectURL(new Blob([body],{type:'text/plain;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download=`${fileName}-transcript.txt`;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function deleteSavedSession(session){if(!confirm(`Delete the saved session for ${session.company||'this interview'}? This cannot be undone.`))return;if(activeLocalSession?.id===session.id){activeLocalSession=null;localStorage.removeItem('fullyPreparedActiveSession');}const sessions=readCompletedSessions().filter(item=>item.id!==session.id);localStorage.setItem('fullyPreparedSessions',JSON.stringify(sessions));renderSessionHistory();}
function resumeSavedSession(session){activeLocalSession={...session,status:'active'};localStorage.setItem('fullyPreparedActiveSession',JSON.stringify(activeLocalSession));sessionLanguageControl.value=activeLocalSession.language||'en';if(activeLocalSession.model){if(![...interviewModelControl.options].some(option=>option.value===activeLocalSession.model))interviewModelControl.add(new Option(activeLocalSession.model,activeLocalSession.model));interviewModelControl.value=activeLocalSession.model;}const liveLanguage=document.querySelector('.live-controls select[aria-label="Call language"]');if(liveLanguage)liveLanguage.value=activeLocalSession.language||'en';document.querySelector('#messages').replaceChildren();for(const item of activeLocalSession.messages||[]){const message=document.createElement('div');message.className='message';message.appendChild(document.createTextNode(item.text||''));const source=document.createElement('small');source.textContent=item.source||'Session';message.appendChild(source);document.querySelector('#messages').appendChild(message);}document.querySelector('#sessionsView').classList.add('hidden');document.querySelector('#placeholderView').classList.add('hidden');document.querySelector('#settingsView').classList.add('hidden');document.querySelector('#mockFlow').classList.add('hidden');liveInterview.classList.remove('hidden');pageTitle.textContent='Mock Interview';pageSubtitle.textContent='Resume your saved practice session.';document.querySelector('#micStatus').textContent='Mic off';pauseButton.textContent='Pause';resumeSessionClock(activeLocalSession.elapsedSeconds);}
let openTranscriptSession=null;
function saveSessionReview(session,changes){
  if(!session)return;
  Object.assign(session,changes);
  if(activeLocalSession?.id===session.id){activeLocalSession={...activeLocalSession,...changes};localStorage.setItem('fullyPreparedActiveSession',JSON.stringify(activeLocalSession));}
  const sessions=readCompletedSessions().map(item=>item.id===session.id?{...item,...changes}:item);
  if(!sessions.some(item=>item.id===session.id)&&session.status!=='active')sessions.push({...session,...changes});
  localStorage.setItem('fullyPreparedSessions',JSON.stringify(sessions));
}
function ensureTranscriptReviewControls(panel,list){
  let review=document.querySelector('#transcriptReview');if(review)return review;
  review=document.createElement('section');review.id='transcriptReview';review.className='transcript-review';
  const heading=document.createElement('h3');heading.textContent='Session debrief';
  const note=document.createElement('p');note.textContent='AI summary uses your configured model endpoint. Hosted endpoints receive transcript text.';
  const generate=document.createElement('button');generate.type='button';generate.id='generateSessionSummary';generate.className='outline-button';generate.textContent='Generate summary';
  const status=document.createElement('p');status.id='sessionSummaryStatus';status.setAttribute('role','status');status.setAttribute('aria-live','polite');
  const summary=document.createElement('div');summary.id='sessionSummary';summary.className='session-summary';summary.setAttribute('aria-label','Generated session summary');
  const followupLabel=document.createElement('label');followupLabel.htmlFor='sessionFollowups';followupLabel.textContent='Follow-up notes';
  const followups=document.createElement('textarea');followups.id='sessionFollowups';followups.maxLength=4000;followups.rows=3;followups.placeholder='Write practice goals or next steps…';
  generate.addEventListener('click',async()=>{
    const session=openTranscriptSession,config=currentModelConfig();
    if(!session)return;
    if(!config.model){status.textContent='Save and test a model in Configure model before generating a summary.';return;}
  const transcript=(session.messages||[]).map(item=>`${item.source||'Session'}: ${item.text||''}`).join('\n').slice(0,20000);
    if(!transcript.trim()){status.textContent='There are no transcript messages to summarize yet.';return;}
    generate.disabled=true;generate.textContent='Generating…';status.textContent='Summarizing with your selected model…';
    try{
      const result=await window.fullyPrepared.models.chat({provider:config.provider,endpoint:config.endpoint,model:config.model,messages:[
        {role:'system',content:window.FullyPreparedPromptTemplates.get('summarizer')},
        {role:'user',content:`Company: ${session.company||'Not specified'}\nRole: ${session.jobDescription||'Not specified'}\nTranscript:\n${transcript}`}
      ]});
      const text=result.message?.content?.trim();if(!text)throw new Error('The model returned an empty summary');
      summary.textContent=text;saveSessionReview(session,{summary:text,summaryModel:config.model,summaryAt:new Date().toISOString()});status.textContent='Summary saved on this device.';
    }catch(error){status.textContent=`Could not generate summary: ${error.message}`;}
    finally{generate.disabled=false;generate.textContent='Generate summary';}
  });
  followups.addEventListener('input',()=>{if(openTranscriptSession)saveSessionReview(openTranscriptSession,{followupNotes:followups.value});});
  review.append(heading,note,generate,status,summary,followupLabel,followups);panel.insertBefore(review,list);return review;
}
function openTranscript(session){
  openTranscriptSession=session;
  document.querySelector('#transcriptTitle').textContent=session.company||'Mock interview';
  document.querySelector('#transcriptMeta').textContent=`${new Date(session.startedAt).toLocaleString()} · ${session.model||'Local model'} · ${session.language||'en'}`;
  const list=document.querySelector('#transcriptMessages'),panel=document.querySelector('.transcript-panel');list.replaceChildren();
  let privacyNotice=document.querySelector('#transcriptNotSaved');if(!privacyNotice){privacyNotice=document.createElement('p');privacyNotice.id='transcriptNotSaved';privacyNotice.className='transcript-search-empty';panel.insertBefore(privacyNotice,list);}privacyNotice.hidden=session.saveTranscript!==false;privacyNotice.textContent='Transcript saving was turned off for this session. Only session metadata is available.';
  for(const item of session.messages||[]){const line=document.createElement('div');line.className='transcript-line';line.textContent=item.text||'';const source=document.createElement('small');source.textContent=item.source||'Session';line.appendChild(source);list.appendChild(line);}
  ensureTranscriptReviewControls(panel,list);
  const savedSummary=document.querySelector('#sessionSummary');savedSummary.textContent=session.summary||'';
  const followupNotes=document.querySelector('#sessionFollowups');followupNotes.value=session.followupNotes||'';
  document.querySelector('#sessionSummaryStatus').textContent=session.summary?`Saved summary · ${session.summaryModel||'model'} · ${session.summaryAt?new Date(session.summaryAt).toLocaleString():''}`:'';
  let search=document.querySelector('#transcriptSearch');
  if(!search){search=document.createElement('input');search.type='search';search.id='transcriptSearch';search.className='transcript-search';search.setAttribute('aria-label','Search this transcript');search.placeholder='Search this transcript';panel.insertBefore(search,list);}
  let noResults=document.querySelector('#transcriptSearchEmpty');
  if(!noResults){noResults=document.createElement('p');noResults.id='transcriptSearchEmpty';noResults.className='transcript-search-empty';noResults.setAttribute('role','status');noResults.textContent='No transcript messages match that search.';noResults.hidden=true;panel.insertBefore(noResults,list);}
  search.value='';search.oninput=()=>{const query=search.value.trim().toLowerCase();let visible=0;for(const line of list.children){line.hidden=!!query&&!line.textContent.toLowerCase().includes(query);if(!line.hidden)visible++;}noResults.hidden=!query||visible>0;};
  document.querySelector('#transcriptModal').classList.remove('hidden');search.focus();
}
document.querySelector('#closeTranscript').addEventListener('click',()=>document.querySelector('#transcriptModal').classList.add('hidden'));
document.querySelector('#clearHistory').addEventListener('click',()=>{if(confirm('Delete all saved local sessions? This cannot be undone.')){localStorage.removeItem('fullyPreparedSessions');if(activeLocalSession?.status==='interrupted'){activeLocalSession=null;localStorage.removeItem('fullyPreparedActiveSession');}renderSessionHistory();}});
document.querySelector('#disconnectLive').addEventListener('click',()=>{if(activeLocalSession){const messages=activeLocalSession.saveTranscript===false?[]:[...document.querySelectorAll('#messages .message')].map(message=>{const small=message.querySelector('small');return{text:[...message.childNodes].filter(node=>node.nodeType===Node.TEXT_NODE).map(node=>node.textContent).join('').trim(),source:small?.textContent||''};});activeLocalSession=window.FullyPreparedSessionState.completeSession(activeLocalSession,messages,sessionClock);localStorage.setItem('fullyPreparedActiveSession',JSON.stringify(activeLocalSession));localStorage.setItem('fullyPreparedLastSession',JSON.stringify(activeLocalSession));const sessions=readCompletedSessions().filter(session=>session.id!==activeLocalSession.id);sessions.push(activeLocalSession);localStorage.setItem('fullyPreparedSessions',JSON.stringify(sessions));renderSessionHistory();}});
renderSessionHistory();

// Route every provider operation through the isolated Electron main process.
const providerTestButton=document.querySelector('#testOllama');
providerTestButton?.addEventListener('click',async(event)=>{
  event.preventDefault();event.stopImmediatePropagation();
  const status=document.querySelector('#saveStatus');
  const provider=document.querySelector('#providerSelect').value;
  const endpoint=document.querySelector('#endpointUrl').value.trim();
  if(!endpoint){status.textContent='Enter an endpoint URL before testing.';return;}
  providerTestButton.disabled=true;providerTestButton.textContent='Testing…';status.textContent='Checking provider and loading models…';
  try{
    const result=await window.fullyPrepared.models.list({provider,endpoint,apiKey:document.querySelector('#apiKey').value});
    populateModels(result.models||[]);
    status.textContent=result.models?.length?`Connected — ${result.models.length} model${result.models.length===1?'':'s'} available`:'Connected — no models were listed';
    providerTestButton.textContent='Connected';
  }catch(error){status.textContent=`Could not connect: ${error.message}`;providerTestButton.textContent='Try again';}
  finally{providerTestButton.disabled=false;}
},{capture:true});

document.querySelector('#saveModel')?.addEventListener('click',async(event)=>{
  event.preventDefault();event.stopImmediatePropagation();
  const status=document.querySelector('#saveStatus');
  const model=document.querySelector('#modelName').value.trim();
  const endpoint=document.querySelector('#endpointUrl').value.trim();
  const provider=document.querySelector('#providerSelect').value;
  const apiKey=document.querySelector('#apiKey').value;
  const speechMode=document.querySelector('#speechMode').value;
  const speechEndpoint=document.querySelector('#speechEndpoint').value.trim()||'http://127.0.0.1:8080';
  if(!model||!endpoint){showFoundationToast('Enter both a model name and endpoint URL.','error');return;}
  try{
    await window.fullyPrepared.models.storeApiKey(apiKey);
    const values={providerSelect:provider,modelName:model,endpointUrl:endpoint};
    localStorage.setItem('fullyPreparedModel',JSON.stringify(values));
    resetSessionModelTest();
    if(![...interviewModelControl.options].some(option=>option.value===model))interviewModelControl.add(new Option(model,model));interviewModelControl.value=model;saveSessionPreferences();
    localStorage.setItem('fullyPreparedSpeechSettings',JSON.stringify({mode:speechMode,endpoint:speechEndpoint}));
    document.querySelector('#apiKey').value='';
    status.textContent='Saved locally; API key stored with device encryption';
    showFoundationToast('Model settings saved on this device.','success');
  }catch(error){status.textContent=`Could not save securely: ${error.message}`;showFoundationToast('Could not save the API key securely on this device.','error');}
},{capture:true});

if(saved?.apiKey&&window.fullyPrepared?.models?.storeApiKey){
  window.fullyPrepared.models.storeApiKey(saved.apiKey).then(()=>{
    delete saved.apiKey;localStorage.setItem('fullyPreparedModel',JSON.stringify(saved));
    document.querySelector('#apiKey').value='';
    document.querySelector('#saveStatus').textContent='Existing API key moved to device-encrypted storage';
  }).catch(error=>{
    document.querySelector('#saveStatus').textContent=`Legacy API key needs attention: ${error.message}`;
  });
}

const answerPreferenceDefaults={format:'Script + bullets',length:'Balanced',tone:'Simple',questionType:'Behavioral'};
const answerPreferenceChoices={format:['Script + bullets','Bullets only','Concise script'],length:['Short','Balanced','Detailed'],tone:['Simple','Professional','Conversational']};
function readAnswerPreferences(){try{return{...answerPreferenceDefaults,...JSON.parse(localStorage.getItem('fullyPreparedAnswerPreferences')||'{}')}}catch{return{...answerPreferenceDefaults}}}
let pendingAnswerPreferences=readAnswerPreferences();
const answerPreferenceButtons=[...document.querySelectorAll('#answerPrefs .answer-option')];
const preferenceKeys=['format','length','tone'];
const questionTypeControl=document.querySelector('#answerPrefs .answer-preview select');
function renderAnswerPreferenceControls(){answerPreferenceButtons.forEach((button,index)=>{button.dataset.preference=preferenceKeys[index];const small=button.querySelector('small');if(small)small.textContent=`${pendingAnswerPreferences[preferenceKeys[index]]}　›`;});if(questionTypeControl)questionTypeControl.value=pendingAnswerPreferences.questionType;}
renderAnswerPreferenceControls();
answerPreferenceButtons.forEach(button=>button.addEventListener('click',()=>{const key=button.dataset.preference;const choices=answerPreferenceChoices[key];const current=choices.indexOf(pendingAnswerPreferences[key]);pendingAnswerPreferences[key]=choices[(current+1)%choices.length];renderAnswerPreferenceControls();}));
questionTypeControl?.addEventListener('change',()=>{pendingAnswerPreferences.questionType=questionTypeControl.value;});
document.querySelector('#saveAnswerPrefs')?.addEventListener('click',event=>{event.preventDefault();event.stopImmediatePropagation();localStorage.setItem('fullyPreparedAnswerPreferences',JSON.stringify(pendingAnswerPreferences));document.querySelector('#answerPrefs').classList.add('hidden');showFoundationToast('Answer preferences saved on this device.','success');},{capture:true});
document.querySelector('.set-default')?.addEventListener('click',()=>{pendingAnswerPreferences={...answerPreferenceDefaults};renderAnswerPreferenceControls();});
function getAnswerStyleInstructions(){const preferences=readAnswerPreferences();return `\nAnswer preferences: question type ${preferences.questionType}; format ${preferences.format}; length ${preferences.length}; tone ${preferences.tone}.`;}

const instructionButtons=[...document.querySelectorAll('#mockPreferences .preference-row button.outline-button')];
const addInstructionButton=instructionButtons[1];
function refreshInstructionButton(){const instruction=localStorage.getItem('fullyPreparedInterviewInstruction')||'';if(addInstructionButton)addInstructionButton.textContent=instruction?'Edit guidance':'＋ Add';}
refreshInstructionButton();
const instructionModal=document.createElement('div');instructionModal.className='instruction-modal hidden';instructionModal.id='instructionModal';instructionModal.setAttribute('role','dialog');instructionModal.setAttribute('aria-modal','true');instructionModal.setAttribute('aria-labelledby','instructionTitle');instructionModal.innerHTML='<div class="instruction-dialog-panel"><p class="settings-kicker">MOCK INTERVIEW</p><h2 id="instructionTitle">AI interviewer guidance</h2><p>Give the interviewer extra context or a preferred approach. This stays on this device.</p><label for="interviewInstructionInput">Instructions</label><textarea id="interviewInstructionInput" maxlength="2000" placeholder="For example: focus on collaboration and ask one follow-up question."></textarea><div class="instruction-dialog-actions"><button type="button" id="removeInterviewInstruction">Remove</button><span></span><button type="button" id="cancelInterviewInstruction">Cancel</button><button type="button" id="saveInterviewInstruction" class="primary">Save guidance</button></div></div>';
document.querySelector('#mockPreferences').appendChild(instructionModal);
const instructionInput=document.querySelector('#interviewInstructionInput');
function closeInstructionModal(){instructionModal.classList.add('hidden');addInstructionButton?.focus();}
addInstructionButton?.addEventListener('click',()=>{instructionInput.value=localStorage.getItem('fullyPreparedInterviewInstruction')||'';instructionModal.classList.remove('hidden');instructionInput.focus();});
document.querySelector('#cancelInterviewInstruction').addEventListener('click',closeInstructionModal);
document.querySelector('#saveInterviewInstruction').addEventListener('click',()=>{const cleaned=instructionInput.value.trim().slice(0,2000);if(cleaned)localStorage.setItem('fullyPreparedInterviewInstruction',cleaned);else localStorage.removeItem('fullyPreparedInterviewInstruction');refreshInstructionButton();closeInstructionModal();showFoundationToast(cleaned?'Interviewer guidance saved.':'Interviewer guidance removed.','success');});
document.querySelector('#removeInterviewInstruction').addEventListener('click',()=>{localStorage.removeItem('fullyPreparedInterviewInstruction');instructionInput.value='';refreshInstructionButton();closeInstructionModal();showFoundationToast('Interviewer guidance removed.','success');});
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!instructionModal.classList.contains('hidden'))closeInstructionModal();});
instructionModal.addEventListener('keydown',event=>{if(event.key!=='Tab')return;const controls=[...instructionModal.querySelectorAll('textarea,button')].filter(control=>!control.disabled);const first=controls[0],last=controls.at(-1);if(event.shiftKey&&document.activeElement===first){event.preventDefault();last.focus();}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus();}});

document.querySelector('#answerPrefs')?.addEventListener('transitionend',()=>{pendingAnswerPreferences=readAnswerPreferences();renderAnswerPreferenceControls();});
document.querySelector('#openAnswerPrefs')?.addEventListener('click',()=>{pendingAnswerPreferences=readAnswerPreferences();renderAnswerPreferenceControls();});

// Keep asynchronous interviewer/model callbacks from speaking or writing into a paused session.
const addLiveMessageBeforePauseGuard=addLiveMessage;
addLiveMessage=function(text,source='Fully Prepared'){if(sessionPaused&&['Interviewer','Fully Prepared','You'].includes(source))return;addLiveMessageBeforePauseGuard(text,source);};
const speakInterviewerBeforePauseGuard=speakInterviewer;
speakInterviewer=function(text){if(sessionPaused)return;speakInterviewerBeforePauseGuard(text);};
const resumeSavedSessionBeforePauseUi=resumeSavedSession;
resumeSavedSession=function(session){sessionPaused=false;resumeSavedSessionBeforePauseUi(session);currentInterviewQuestion=[...(activeLocalSession?.messages||[])].reverse().find(item=>/interviewer/i.test(item.source||''))?.text||'';voiceInterviewActive=true;renderSessionPauseState();if(currentInterviewQuestion)speakInterviewer(currentInterviewQuestion);else void startVoiceInterview();};
